    const bytes = readFileSync(path);
    if (bytes.includes(0)) return false;
    return /^(?:<{7} |>{7} )/m.test(bytes.toString("utf8"));
  } catch {
    // Gone from the worktree, which is a resolution: `add -A` stages the deletion.
    return false;
